/** Where a Job is in its life, from `job-statuses.toml`. Not a rendering. */
export type Lifecycle = {
  /** Whether the Job is over here. */
  readonly terminal: boolean;
  /** `Working`, `Waited on` or `N/A` — what the Job is doing. */
  readonly mode: string;
  /**
   * `Person`, `Drone` or `None` — who the Job is waiting on.
   *
   * **Not the same question as `mode`.** `piloted` is `Working` and its
   * actor is a person; `queued` is `Waited on` and its actor is a drone. A
   * surface grouping the statuses that stop until somebody reads them wants
   * this field, and answers wrongly with either half of it alone.
   */
  readonly whoIsActing: string;
};

